    def solve(self, n, k, s, t):
        while t % n != 0:
            delta = (s < k) - (s >= k)
            s = (s + n + delta) % n
            t -= 1
        t //= n

        when = [-1] * n
        for left in range(t, 0, -1):
            if when[s] != -1:
                period = when[s] - left
                for i in range(n):
